import json
import glob
import numpy as np
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D

# 1. Grab the first JSON file generated by SpinePose
json_files = sorted(glob.glob("output_data/*.json"))
if not json_files:
    print("No JSON files found in output_data/. Run SpinePose first!")
    exit()

target_frame = json_files[0]
print(f"Loading 3D biomechanical data from: {target_frame}")

# 2. Parse the JSON data
with open(target_frame, 'r') as f:
    data = json.load(f)

if len(data['people']) == 0:
    print("No person detected in this frame.")
    exit()

# 3. Extract the 3D keypoints
# The flat array format is: [x0, y0, z0, c0, x1, y1, z1, c1, ...]
kpts_3d = data['people'][0]['pose_keypoints_3d']
num_keypoints = 37

# Reshape into a cleaner 2D matrix (37 rows, 4 columns)
points = np.array(kpts_3d).reshape((num_keypoints, 4))
X = points[:, 0]
Y = points[:, 1]
Z = points[:, 2]
confidence = points[:, 3]

# 4. Set up the interactive 3D plot
fig = plt.figure(figsize=(10, 8))
ax = fig.add_subplot(111, projection='3d')

# Map axes to stand the skeleton upright
# (Inverting Y because image coordinates map Y downwards)
plot_x = X
plot_y = Z       # Depth maps to the floor plane
plot_z = -Y      # Height maps to the vertical axis

# Draw the keypoint nodes
ax.scatter(plot_x, plot_y, plot_z, c='red', s=30, edgecolor='black')

# 5. Define the skeletal structure
body_edges = [
    (0,1), (0,2), (1,3), (2,4), (5,7), (7,9), (6,8), (8,10),
    (11,13), (13,15), (12,14), (14,16), (5,6), (11,12), (5,11), (6,12)
]
spine_edges = [
    (17,18), (18,19), (19,20), (20,21), (21,22), (22,23), (23,24), (24,25)
]

# Helper function to connect the joints with lines
def draw_skeleton(edges, color, width):
    for start, end in edges:
        if confidence[start] > 0 and confidence[end] > 0:
            ax.plot([plot_x[start], plot_x[end]], 
                    [plot_y[start], plot_y[end]], 
                    [plot_z[start], plot_z[end]], 
                    c=color, linewidth=width)

# Draw standard limbs (blue) and the spine (orange)
draw_skeleton(body_edges, '#4a90e2', 2)
draw_skeleton(spine_edges, '#ff9500', 4)

# 6. Format the 3D environment
ax.set_title("SIMSPINE 3D Reconstruction (Frame 1)")
ax.set_xlabel("X (Width)")
ax.set_ylabel("Z (Depth)")
ax.set_zlabel("Y (Height)")

# Render the interactive window
plt.show()